  client_id = (New-Guid).Guid
  prompt = @{
    '1' = @{
      class_type = 'LoadImage'
      inputs = @{ image = 'view.png' }
    }
    '2' = @{
      class_type = 'Describe2PromptIdeogram'
      inputs = @{
        image = @('1', 0)
        mode = 'mock'
        model_id = 'microsoft/Florence-2-base-ft'
        hf_cache_dir = 'E:\AI_MODELS\describe2prompt\huggingface'
        filename_prefix = 'view_b_mock'
        output_dir = 'C:\Users\User\Documents\New project\describe2prompt_comfyui'
      }
    }
    '3' = @{
      class_type = 'Describe2PromptSaveText'
      inputs = @{
        text = @('2', 0)
        filename_prefix = 'view_b_mock'
        output_dir = 'C:\Users\User\Documents\New project\describe2prompt_comfyui'
      }
    }
  }
} | ConvertTo-Json -Depth 20 -Compress
$body | Out-File -LiteralPath 'C:\Users\User\Documents\New project\outputs\view_b_mock_body.json' -Encoding utf8
"body bytes=$((Get-Item 'C:\Users\User\Documents\New project\outputs\view_b_mock_body.json').Length)"
$req = [System.Net.HttpWebRequest]::Create('http://127.0.0.1:8188/prompt')
$req.Method = 'POST'; $req.ContentType = 'application/json'; $req.Timeout = 60000
$bytes = [System.Text.Encoding]::UTF8.GetBytes($body)
$req.ContentLength = $bytes.Length
$stream = $req.GetRequestStream(); $stream.Write($bytes, 0, $bytes.Length); $stream.Close()
$resp = $req.GetResponse()
$sr = New-Object System.IO.StreamReader($resp.GetResponseStream())
"submit: $($sr.ReadToEnd())"
$sr.Close(); $resp.Close()","justification":"Прогон mock-режима, чтобы зафиксировать результат","max_output_tokens":2000,"shell":"powershell"}

